mapper.select:
SELECT r.reservation_code AS reservationCode, r.class_code AS classCode, c.name AS className,
/* 💡 class 테이블(c)에서 operator_code를 직접 가져와 유실 방지 */ c.operator_code AS operatorCode, cr.activity_name AS activityName,
img.image AS classImg, c.address AS address, TO_CHAR(r.reservation_date, 'YYYY.MM.DD(DY) HH24:MI') AS reservationDate, TO_CHAR(r.reservation_date, 'YYYY.MM.DD(DY) HH24:MI') AS classDate,
/* [상태 조건] 1. 취소 관련 상태('취소', '취소완료', '환불완료' 등)인 경우 수강완료로 변경하지 않고 기존 취소 상태 유지 2. 수강 일시(reservation_date)가 현재 시간(SYSDATE)을 지난 경우 '수강완료'로 판별 3. 그 외 수강 일시 이전인 정상 구매건은 기본 '예약' (또는 r.status 기본값) 상태 유지 */ CASE WHEN r.status LIKE '%취소%' OR r.status LIKE '%환불%' THEN r.status WHEN r.reservation_date < SYSDATE THEN '수강완료' ELSE r.status END AS classStatus FROM reservation r JOIN class c ON r.class_code = c.class_code
/* 💡 class(c)의 operator_code와 creator(cr)의 operator_code 조인 */ LEFT JOIN creator cr ON c.operator_code = cr.operator_code
LEFT JOIN class_img img ON c.class_code = img.class_code AND img.type = '대표' AND img.sort_order = 1 WHERE r.member_code = TO_NUMBER(#{memberCode})
AND NOT (r.status LIKE '%취소%' OR r.status LIKE '%환불%') AND r.reservation_date >= SYSDATE
AND NOT (r.status LIKE '%취소%' OR r.status LIKE '%환불%') AND (r.status IN ('수강완료', '이용 완료') OR r.reservation_date < SYSDATE)
AND (r.status LIKE '%취소%' OR r.status LIKE '%환불%')
AND r.status = #{status}
ORDER BY r.reservation_code DESC

SELECT r.reservation_code AS reservationCode, r.people_number AS reservationNum, TO_CHAR(r.reservation_date, 'YYYY.MM.DD HH24:MI') AS reservationDate, TO_CHAR(r.reservation_date, 'YYYY.MM.DD HH24:MI') AS classDate,
/* 상단용: 예약/수강 상태 (시간 경과 체크) */ CASE WHEN r.status IN ('취소완료', '환불완료', '취소됨') THEN r.status WHEN r.reservation_date < SYSDATE THEN '수강완료' ELSE r.status END AS classStatus,
r.price AS totalPrice,
c.class_code AS classCode, c.operator_code AS operatorCode, c.category_code AS categoryCode, c.name AS className, img.image AS classImg, c.price AS classPrice, c.address AS address, c.address2 AS address2, c.single_introduce AS singleIntroduce, c.introduce AS introduce, TO_CHAR(c.write_date, 'YYYY.MM.DD HH24:MI') AS writeDate,
/* 하단용: 결제 상태 */ p.payment_code AS paymentCode, p.amount AS finalPrice, p.means AS paymentMethod, TO_CHAR(p.payment_date, 'YYYY.MM.DD HH24:MI') AS paymentDate, p.status AS paymentStatus, p.PG_code AS pgCode, p.refund AS refund, TO_CHAR(p.refund_date, 'YYYY.MM.DD HH24:MI') AS refundDate FROM reservation r JOIN class c ON r.class_code = c.class_code LEFT JOIN class_img img ON c.class_code = img.class_code AND img.type = '대표' AND img.sort_order = 1 LEFT JOIN payment p ON r.reservation_code = p.reservation_code WHERE r.reservation_code = TO_NUMBER(#{reservationCode})
